import{d as l,C as o,o as h,c as d,j as i,a as e,E as a,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"中庸·第27章","description":"《中庸》第 27 章——大哉圣人之道：发育万物，峻极于天；待其人而后行；尊德性而道问学，致广大而尽精微，极高明而道中庸。","frontmatter":{"title":"中庸·第27章","description":"《中庸》第 27 章——大哉圣人之道：发育万物，峻极于天；待其人而后行；尊德性而道问学，致广大而尽精微，极高明而道中庸。","category":"guide","aliases":["第27章","中庸第27章","大哉圣人之道"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-27.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-27.md","lastUpdated":1790316338000}'),u={name:"lizhimingde/sishu-wujing/zhongyong/chapter-27.md"},x=l({...u,setup(y){const r=[{id:"dayang",label:"大哉圣人之道 · 发育万物，峻极于天",showLabel:!0,sentences:[["大哉圣人之道！",{text:"洋洋乎",glossary:"yangyang"},"！发育万物，",{text:"峻极于天",glossary:"junjitian"},"。"]],note:"「大哉圣人之道！」——先赞叹一句。「洋洋乎！发育万物，峻极于天」：浩浩洋洋，发育万物，高大至于天。此章自此展开。"},{id:"liyi",label:"礼仪三百 · 威仪三千 · 待其人而后行",showLabel:!0,sentences:[[{text:"优优",glossary:"youyou"},"大哉！礼仪三百，威仪三千。待其人而后行。故曰苟不至德，至道不",{text:"凝",glossary:"ning"},"焉。"]],note:"「优优大哉！礼仪三百，威仪三千」——优裕广大啊！礼仪有三百条，威仪有三千条。然而「待其人而后行」：要等到那样的人才行得通。故曰「苟不至德，至道不凝焉」——若无至德，则至道凝聚不起。"},{id:"zundexing",label:"尊德性而道问学 · 致广大而尽精微 · 极高明而道中庸",showLabel:!0,sentences:[["故君子",{text:"尊德性",glossary:"zundexing"},"而",{text:"道问学",glossary:"daowenxue"},"，",{text:"致广大",glossary:"zhiguangda"},"而",{text:"尽精微",glossary:"jinjingwei"},"，",{text:"极高明",glossary:"jigaoming"},"而",{text:"道中庸",glossary:"daozhongyong"},"。"],["温故而知新，敦厚以崇礼。"]],note:"为学之要，在三对「而」字句：「尊德性而道问学」（尊崇德性，又由问学入手），「致广大而尽精微」（极广大，又尽精微），「极高明而道中庸」（极高明，又行乎中庸）。又「温故而知新，敦厚以崇礼」。此五句为《中庸》的为学总纲。"},{id:"baoshen",label:"居上不骄 · 为下不倍 · 既明且哲，以保其身",showLabel:!0,sentences:[["是故居上不骄，为下不",{text:"倍",glossary:"bubei"},"，国有道其言足以兴，国无道其默足以容。《诗》曰：",{text:"既明且哲",glossary:"jiming"},"，",{text:"以保其身",glossary:"baoshen"},"，其此之谓与！"]],note:"处世之守：「居上不骄，为下不倍（背）」；「国有道其言足以兴，国无道其默足以容」——国治则言足以兴国，国乱则默足以自容。引《诗》「既明且哲，以保其身」——明哲保身，正是此谓。"}],g=[{id:"yangyang",term:"洋洋乎",pinyin:"yáng yáng hū",meaning:"流动充满。朱注：「此言道之极于至大而无外也。」"},{id:"junjitian",term:"峻极于天",pinyin:"jùn jí yú tiān",meaning:"峻：高大。高到极处，与天齐。"},{id:"youyou",term:"优优",pinyin:"yōu yōu",meaning:"朱注：「充足有余之意。」"},{id:"ning",term:"凝",pinyin:"níng",meaning:"聚、成。朱注：「至德，谓其人。凝，聚也，成也。」"},{id:"zundexing",term:"尊德性",pinyin:"zūn dé xìng",meaning:"朱注：「尊者，恭敬奉持之意。德性者，吾所受于天之正理。」——存心之事。"},{id:"daowenxue",term:"道问学",pinyin:"dào wèn xué",meaning:"道：由。朱注：「道问学，所以致知而尽乎道体之细也。」——致知之事。"},{id:"zhiguangda",term:"致广大",pinyin:"zhì guǎng dà",meaning:"推致广大。"},{id:"jinjingwei",term:"尽精微",pinyin:"jìn jīng wēi",meaning:"穷尽精微。"},{id:"jigaoming",term:"极高明",pinyin:"jí gāo míng",meaning:"极尽高明。"},{id:"daozhongyong",term:"道中庸",pinyin:"dào zhōng yōng",meaning:"由中庸而行。朱注以此五句「大小相资，首尾相应，圣贤所示入德之方，莫详于此」。"},{id:"bubei",term:"不倍",pinyin:"bù bèi",meaning:"倍：同「背」。为下不倍，即在下位不违背（不越分）。"},{id:"jiming",term:"既明且哲",pinyin:"jì míng qiě zhé",meaning:"《诗·大雅·烝民》句。既明白又明智。"},{id:"baoshen",term:"以保其身",pinyin:"yǐ bǎo qí shēn",meaning:"用以保全自身。"}];return(p,n)=>{const s=o("DaoTextReading"),t=o("DaoKeywordCards");return h(),d("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第27章",tabindex:"-1"},[e("中庸·第27章 "),i("a",{class:"header-anchor",href:"#中庸·第27章","aria-label":'Permalink to "中庸·第27章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[e("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,[e("第二十七章先叹「圣人之道」之大（洋洋发万物、峻极于天）与大之细（礼仪三百、威仪三千），再说「待其人而后行」，然后给出全篇最著名的修养总纲——"),i("strong",null,"尊德性而道问学，致广大而尽精微，极高明而道中庸"),e("。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),a(s,{colophon:"大哉圣人之道 · 待其人而后行 · 尊德性而道问学",tone:"ink",sections:r,glossary:g,"default-mode":"slips","aria-label":"中庸·第27章 原文"}),n[3]||(n[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[e("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),a(t,{items:[{term:"洋洋乎",pinyin:["yáng","yáng","hū"],meaning:"流动充满——道之至大无外。"},{term:"峻极于天",pinyin:["jùn","jí","yú","tiān"],meaning:"峻：高大。高与天齐。"},{term:"优优大哉",pinyin:["yōu","yōu","dà","zāi"],meaning:"优优：充足有余——道之至小无间。"},{term:"礼仪三百",pinyin:["lǐ","yí","sān","bǎi"],meaning:"经礼三百条。"},{term:"威仪三千",pinyin:["wēi","yí","sān","qiān"],meaning:"曲礼三千条。"},{term:"待其人而后行",pinyin:["dài","qí","rén","ér","hòu","xíng"],meaning:"道要等有德之人才能施行。"},{term:"至道不凝",pinyin:["zhì","dào","bù","níng"],meaning:"凝：聚、成。无至德，则至道不成。"},{term:"尊德性",pinyin:["zūn","dé","xìng"],meaning:"恭敬奉持本有的德性——存心之事。"},{term:"道问学",pinyin:["dào","wèn","xué"],meaning:"道：由。由问学而入——致知之事。朱注：「二者修德凝道之大端也。」"}]}),a(t,{items:[{term:"致广大而尽精微",pinyin:["zhì","guǎng","dà","jìn","jīng","wēi"],meaning:"把广大的推开，也把精微的穷尽——大与细两头俱到。"},{term:"极高明而道中庸",pinyin:["jí","gāo","míng","dào","zhōng","yōng"],meaning:"达到极高明，仍由中庸而行——高不脱离平常。"},{term:"温故知新",pinyin:["wēn","gù","zhī","xīn"],meaning:"温习旧学而知新。"},{term:"敦厚崇礼",pinyin:["dūn","hòu","chóng","lǐ"],meaning:"加厚自身而崇尚礼。"},{term:"既明且哲",pinyin:["jì","míng","qiě","zhé"],meaning:"《诗·大雅·烝民》句：既明白又明智。"},{term:"以保其身",pinyin:["yǐ","bǎo","qí","shēn"],meaning:"用以保全自身。"}]}),n[4]||(n[4]=m('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>大哉圣人之道 · 峻极于天</strong>：伟大啊，圣人之道！流动充满，发育万物，高与天齐。</p><p><strong>礼仪三百 · 待其人而后行</strong>：充足有余，伟大啊！礼仪有三百，威仪有三千。这要等有那样的人，才能施行。所以说，如果没有至德，至道就不会凝聚成形。</p><p><strong>尊德性而道问学</strong>：所以君子恭敬奉持本有的德性，又由问学而入；推致广大，又穷尽精微；达到极高明，仍由中庸而行。温习旧学而获得新知，敦厚自身而崇尚礼。</p><p><strong>居上不骄 · 既明且哲</strong>：因此在上位不骄傲，在下位不越分；国有道时，他的话足以兴起教化，国无道时，他的沉默足以容身。《诗经》说：「既明且哲，以保其身」——大概就是说这个吧！</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第二十七章分三段：</p><ol><li><strong>赞道之大与大之细</strong>：洋洋乎发育万物、峻极于天（至大无外）；优优大哉、礼仪三百、威仪三千（至小无间）</li><li><strong>道要人才能行</strong>：「待其人而后行」「苟不至德，至道不凝」</li><li><strong>修养总纲</strong>：「尊德性而道问学，致广大而尽精微，极高明而道中庸。温故而知新，敦厚以崇礼」——末以「居上不骄，为下不倍」与《诗》句作结</li></ol><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>这五句是全篇的修养总纲</strong>：朱注说它们「大小相资，首尾相应，圣贤所示入德之方，<strong>莫详于此</strong>」——这是朱熹给本篇下的最高评语之一。</li><li><strong>每一句都是「两端相济」</strong>：尊德性（存心／大）—道问学（致知／细）；致广大—尽精微；极高明—道中庸。<strong>单独走任何一头都会偏</strong>，这正是「中庸」二字的方法论。</li><li><strong>「极高明而道中庸」是这一组的眼</strong>：做到极高明的境界，仍然「由中庸而行」——<strong>高明不脱离平常</strong>。这和第 11 章「依乎中庸」、第 27 章的收束完全一致。</li><li><strong>「苟不至德，至道不凝」</strong>：道不会自己落地，得有人把它凝住。这与第 20 章「为政在人」是同一个意思。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>把五句当日课对表</strong>：尊德性／道问学——我今天是只顾存心，还是只顾求知？致广大／尽精微——是光顾大局，还是只抠细节？极高明／道中庸——是空谈高远，还是甘于平常？</li><li><strong>「道中庸」的提醒</strong>：越高明的事，越要用平常的方式做。</li><li><strong>「待其人」</strong>：计划不落地，常常不是方案的问题，是「人」没到位。</li><li><strong>「温故而知新」</strong>：不是两件事，是同一件——旧学里长出新的理解。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>伟大啊，圣人之道——它流动充满，化育万物，高与天齐；它又细密有余，礼仪三百条、威仪三千条。</p><p>这样的道，<strong>要等有那个人，才能行得起来</strong>；没有至德，至道就凝不成形。</p><p>所以君子的功夫是成对做的：<strong>尊德性，也道问学；致广大，也尽精微；极高明，也道中庸；温故而知新，敦厚而崇礼。</strong></p><p>最后两句是处世：在上位不骄傲，在下位不越分；该说时说得起来，该默时容得下自己。</p><p>这一章的关键词是「<strong>而</strong>」——不是二选一，是两端相济。<strong>高明，仍要走平常的路。</strong></p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「尊德性而道问学」——我今天是只顾存心，还是只顾求知？</li><li>「致广大而尽精微」——我偏哪一头？</li><li>「极高明而道中庸」——我有没有「看不上平常事」的时候？</li><li>「待其人而后行」——我的计划不落地，缺的是方案，还是「人」？</li><li>「温故而知新」——我的「故」里，长出过新东西吗？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-26">中庸·第26章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-28">中庸·第28章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',26))])}}});export{c as __pageData,x as default};
